<?php $title='Activity Log';require __DIR__.'/includes/header.php';require_admin();$q=trim($_GET['q']??'');$action=trim($_GET['action']??'');$where=[];$p=[];if($q){$where[]='(user_name_snapshot LIKE ? OR entity_ref LIKE ? OR details LIKE ?)';$like='%'.$q.'%';array_push($p,$like,$like,$like);}if($action){$where[]='action=?';$p[]=$action;}$sql='SELECT * FROM activity_logs '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC LIMIT 200';$s=db()->prepare($sql);$s->execute($p);$rows=$s->fetchAll();?><div class="page-head"><div><h1>Activity Log</h1><p class="muted">Append-only staff and system activity.</p></div></div><form class="search"><input name="q" value="<?=e($q)?>" placeholder="Staff, reference or details"><input name="action" value="<?=e($action)?>" placeholder="Action, e.g. archive created"><button class="btn">Filter</button></form><div class="card table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></td><td><?=e($r['user_name_snapshot'])?></td><td><span class="badge paid"><?=e($r['action'])?></span></td><td><?=e($r['entity_ref']??'')?></td><td><?=e($r['details']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No activity found.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/includes/footer.php';
